SELECT 'FALTA' AS que, e.t AS tabla, e.c AS columna
  FROM JSON_TABLE(@esperadas, '$[*]'
         COLUMNS (t VARCHAR(64) PATH '$.t', c VARCHAR(64) PATH '$.c')) AS e
  LEFT JOIN information_schema.columns k
         ON k.table_schema = 'gestek_datos' AND k.table_name = e.t AND k.column_name = e.c
 WHERE k.column_name IS NULL

UNION ALL

SELECT 'sobra', k.table_name, k.column_name
  FROM information_schema.columns k
  LEFT JOIN JSON_TABLE(@esperadas, '$[*]'
         COLUMNS (t VARCHAR(64) PATH '$.t', c VARCHAR(64) PATH '$.c')) AS e
         ON e.t = k.table_name AND e.c = k.column_name
 WHERE k.table_schema = 'gestek_datos'
   AND k.table_name <> 'archivos'
   AND e.c IS NULL
 ORDER BY 1, 2, 3;
